const app=document.getElementById('app'),toast=document.getElementById('toast');let tab='overview';
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function show(m){toast.textContent=m;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2400)}
async function api(url,opt={}){opt.credentials='same-origin';const r=await fetch(url,opt),j=await r.json().catch(()=>({}));if(!r.ok)throw Error(j.error||'حدث خطأ');return j}
function shell(){app.innerHTML=`<div class="admin-head"><div><h1>لوحة إدارة عقارتكم</h1><small>إدارة المستخدمين والعقارات والاستفسارات والإعلانات المميزة</small></div></div><div class="tabs"><button data-tab="owner-center">مركز قيادة المالك</button><button data-tab="trust-center">الثقة ومكافحة الاحتيال</button><button data-tab="overview">نظرة عامة</button><button data-tab="marketing">التسويق والنمو</button><button data-tab="marketing-roi">ROI التسويق</button><button data-tab="budget-optimizer">محسن الميزانية AI</button><button data-tab="market-forecast">توقع السوق AI</button><button data-tab="ai-executive">المدير التنفيذي AI</button><button data-tab="ai-ops">المدير الذكي</button><button data-tab="executive-bi">ذكاء الأعمال</button><button data-tab="property-ai">ذكاء العقارات</button><button data-tab="market-map">خريطة السوق</button><button data-tab="geocoding">تغطية الخريطة</button><button data-tab="properties">العقارات</button><button data-tab="users">المستخدمون</button><button data-tab="inquiries">الاستفسارات</button><button data-tab="finance">المالية</button><button data-tab="hotel-exec">مركز الفنادق</button><button data-tab="hotel-payouts">تحويلات الفنادق</button><button data-tab="hotel-auto">التسوية الآلية</button><button data-tab="accounting">المحاسبة</button><button data-tab="einvoices">الفوترة الإلكترونية</button><button data-tab="notifications">التنبيهات</button></div><div id="content"></div>`;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()})}
async function render(){document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));const c=document.getElementById('content');try{if(tab==='owner-center')return ownerUnifiedCenter(c);if(tab==='trust-center')return trustCenter(c);if(tab==='overview')return overview(c);if(tab==='marketing')return marketingGrowth(c);if(tab==='marketing-roi')return marketingROI(c);if(tab==='budget-optimizer')return budgetOptimizer77(c);if(tab==='market-forecast')return marketForecast79(c);if(tab==='ai-executive')return aiExecutiveDashboard(c);if(tab==='ai-ops')return aiOperations(c);if(tab==='executive-bi')return executiveBI(c);if(tab==='property-ai')return propertyAI(c);if(tab==='market-map')return marketMap(c);if(tab==='geocoding')return geocoding(c);if(tab==='properties')return properties(c);if(tab==='users')return users(c);if(tab==='inquiries')return inquiries(c);if(tab==='notifications')return notifications(c);if(tab==='hotel-exec')return hotelExecutive(c);if(tab==='hotel-payouts')return hotelPayouts(c);if(tab==='hotel-auto')return hotelAutomation(c);if(tab==='accounting')return accounting(c);if(tab==='einvoices')return einvoices(c);return finance(c)}catch(e){c.innerHTML=`<div class="panel">${esc(e.message)}</div>`}}
async function overview(c){const d=await api('/api/admin/overview');c.innerHTML=`<div class="stats"><div class="stat"><b>${d.users.total}</b><small>إجمالي المستخدمين</small></div><div class="stat"><b>${d.properties.total}</b><small>إجمالي العقارات</small></div><div class="stat"><b>${d.properties.pending}</b><small>إعلانات بانتظار المراجعة</small></div><div class="stat"><b>${d.inquiries.new}</b><small>استفسارات جديدة</small></div><div class="stat"><b>${d.views.total}</b><small>إجمالي المشاهدات</small></div></div><div class="panel"><h3>ملخص سريع</h3><p>المستخدمون النشطون: <b>${d.users.active}</b> — المكاتب العقارية: <b>${d.users.agents}</b> — الإعلانات المميزة: <b>${d.properties.featured}</b> — الاستفسارات الكلية: <b>${d.inquiries.total}</b></p></div>`}
async function properties(c){c.innerHTML='<div class="panel"><div class="toolbar"><input id="q" placeholder="ابحث بالعنوان أو المدينة"><select id="status"><option value="">كل الحالات</option><option value="active">نشط</option><option value="pending">بانتظار المراجعة</option><option value="rejected">مرفوض</option></select><button id="go">بحث</button></div><div class="table-wrap" id="tbl">جاري التحميل...</div></div>';document.getElementById('go').onclick=loadProps;await loadProps()}
async function loadProps(){const q=encodeURIComponent(document.getElementById('q').value),s=encodeURIComponent(document.getElementById('status').value);const d=await api('/api/admin/properties?q='+q+'&status='+s);document.getElementById('tbl').innerHTML=`<table class="table"><tr><th>العقار</th><th>المالك</th><th>السعر</th><th>المشاهدات</th><th>الاستفسارات</th><th>الحالة</th><th>إجراءات</th></tr>${d.data.map(p=>`<tr><td><b>${esc(p.title)}</b><br><small>${esc(p.city)} - ${esc(p.district||'')}</small></td><td>${esc(p.owner_name||'—')}</td><td>$ ${Number(p.price).toLocaleString()}</td><td>${p.views_count}</td><td>${p.inquiry_count}</td><td><span class="badge ${p.status}">${p.status==='active'?'نشط':p.status==='pending'?'مراجعة':'مرفوض'}</span></td><td class="actions"><button class="gold" data-feature="${p.id}">${p.featured?'إلغاء التمييز':'تمييز'}</button><button data-status="${p.id}" data-value="${p.status==='active'?'pending':'active'}">${p.status==='active'?'تعليق':'تفعيل'}</button><button class="danger" data-delete="${p.id}">حذف</button></td></tr>`).join('')}</table>`;document.querySelectorAll('[data-feature]').forEach(b=>b.onclick=async()=>{const p=d.data.find(x=>x.id==b.dataset.feature);await api('/api/admin/properties/'+p.id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({featured:!p.featured})});show('تم تحديث الإعلان المميز');loadProps()});document.querySelectorAll('[data-status]').forEach(b=>b.onclick=async()=>{await api('/api/admin/properties/'+b.dataset.status,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:b.dataset.value})});show('تم تحديث حالة الإعلان');loadProps()});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('حذف الإعلان نهائياً؟'))return;await api('/api/admin/properties/'+b.dataset.delete,{method:'DELETE'});show('تم حذف العقار');loadProps()})}
async function users(c){c.innerHTML='<div class="panel"><div class="toolbar"><input id="uq" placeholder="ابحث بالاسم أو البريد أو الهاتف"><button id="ugo">بحث</button></div><div class="table-wrap" id="utbl">جاري التحميل...</div></div>';document.getElementById('ugo').onclick=loadUsers;await loadUsers()}
async function loadUsers(){const d=await api('/api/admin/users?q='+encodeURIComponent(document.getElementById('uq').value));document.getElementById('utbl').innerHTML=`<table class="table"><tr><th>المستخدم</th><th>الهاتف</th><th>الدور</th><th>العقارات</th><th>الحالة</th><th>إجراء</th></tr>${d.data.map(u=>`<tr><td><b>${esc(u.name)}</b><br>${esc(u.email)}</td><td>${esc(u.phone||'—')}</td><td>${esc(u.role)}</td><td>${u.properties_count}</td><td>${u.is_active?'نشط':'موقوف'}</td><td class="actions"><button data-role="${u.id}">تغيير الدور</button><button data-active="${u.id}">${u.is_active?'إيقاف':'تفعيل'}</button></td></tr>`).join('')}</table>`;document.querySelectorAll('[data-active]').forEach(b=>b.onclick=async()=>{const u=d.data.find(x=>x.id==b.dataset.active);await api('/api/admin/users/'+u.id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({is_active:!u.is_active})});show('تم تحديث حالة المستخدم');loadUsers()});document.querySelectorAll('[data-role]').forEach(b=>b.onclick=async()=>{const u=d.data.find(x=>x.id==b.dataset.role);const role=prompt('أدخل الدور: user أو agent أو admin',u.role);if(!role)return;await api('/api/admin/users/'+u.id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({role})});show('تم تحديث الدور');loadUsers()})}
async function inquiries(c){const d=await api('/api/admin/inquiries');c.innerHTML=`<div class="panel"><div class="table-wrap"><table class="table"><tr><th>العقار</th><th>المرسل</th><th>الهاتف</th><th>الرسالة</th><th>الحالة</th><th>التاريخ</th></tr>${d.data.map(i=>`<tr><td>${esc(i.property_title)}</td><td>${esc(i.sender_name)}</td><td>${esc(i.sender_phone||'—')}</td><td>${esc(i.message)}</td><td>${esc(i.status)}</td><td>${new Date(i.created_at).toLocaleString('ar-SY')}</td></tr>`).join('')}</table></div></div>`}

async function notifications(c){const d=await api('/api/admin/notifications/status');c.innerHTML=`<div class="panel"><h3>حالة قنوات التنبيهات</h3><div class="stats"><div class="stat"><b>${d.data.emailReady?'مفعّل':'غير مفعّل'}</b><small>البريد الإلكتروني</small></div><div class="stat"><b>${d.data.pushReady?'مفعّل':'غير مفعّل'}</b><small>Push</small></div><div class="stat"><b>${d.data.whatsappReady?'مفعّل':'غير مفعّل'}</b><small>WhatsApp</small></div></div><p><small>مفاتيح القنوات السرية لا تظهر في الواجهة.</small></p></div><div class="panel"><h3>اختبار قناة</h3><div class="toolbar"><select id="testChannel"><option value="email">البريد</option><option value="push">Push</option><option value="whatsapp">WhatsApp</option><option value="in_app">داخل التطبيق</option></select><button class="gold" id="testNotif">إرسال اختبار</button></div></div>`;document.getElementById('testNotif').onclick=async()=>{try{await api('/api/admin/notifications/test',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({channel:document.getElementById('testChannel').value})});show('تم إرسال الاختبار بنجاح')}catch(e){show(e.message)}}}

async function finance(c){
  c.innerHTML=`<div class="finance-toolbar"><button class="gold" id="finRefresh">تحديث البيانات</button><select id="finOffice"><option value="">اختر مكتباً لكشف الحساب</option></select></div><div id="finStats"></div><div class="finance-grid"><div class="panel"><h3>التحويلات بانتظار الاعتماد</h3><div class="table-wrap" id="pendingPayments">جاري التحميل...</div></div><div class="panel"><h3>كشف حساب المكتب</h3><div id="statement">اختر مكتباً لعرض كشف الحساب.</div></div></div><div class="panel"><h3>جميع المدفوعات</h3><div class="toolbar"><input id="fpq" placeholder="بحث بالمكتب أو العميل أو رقم العملية"><select id="fpp"><option value="">كل طرق الدفع</option><option value="moyasar">Moyasar</option><option value="shamcash">شام كاش</option><option value="syriatel_cash">سيرياتيل كاش</option></select><select id="fps"><option value="">كل الحالات</option><option value="paid">مدفوع</option><option value="pending">معلق</option><option value="cancelled">مرفوض</option><option value="failed">فشل</option><option value="refunded">مسترد</option></select><button id="finSearch">بحث</button></div><div class="table-wrap" id="allPayments">جاري التحميل...</div></div>`;
  document.getElementById('finRefresh').onclick=()=>finance(c);
  document.getElementById('finSearch').onclick=()=>loadFinancePayments();
  const d=await api('/api/admin/finance/overview');
  document.getElementById('finStats').innerHTML=`<div class="stats"><div class="stat"><b>${Number(d.totals.paid_total||0).toLocaleString('ar-SY')}</b><small>إجمالي المدفوع</small></div><div class="stat"><b>${d.totals.paid_payments}</b><small>عمليات مدفوعة</small></div><div class="stat"><b>${d.totals.pending_payments}</b><small>قيد المراجعة</small></div><div class="stat"><b>${d.totals.failed_payments}</b><small>فاشلة</small></div><div class="stat"><b>${d.totals.refunded_payments}</b><small>مستردة</small></div></div>`;
  document.getElementById('pendingPayments').innerHTML=d.pending.length?`<table class="table"><tr><th>المكتب</th><th>العميل</th><th>الطريقة</th><th>المبلغ</th><th>رقم العملية</th><th>التاريخ</th><th>إجراء</th></tr>${d.pending.map(p=>`<tr><td>${esc(p.office_name||'—')}</td><td>${esc(p.user_name||'—')}</td><td>${paymentLabel(p.provider)}</td><td>${Number(p.amount).toLocaleString('ar-SY')} ${esc(p.currency)}</td><td>${esc(p.transaction_reference||'—')}</td><td>${new Date(p.created_at).toLocaleString('ar-SY')}</td><td class="actions"><button class="gold" data-approve="${p.id}">اعتماد</button><button class="danger" data-reject="${p.id}">رفض</button></td></tr>`).join('')}</table>`:'<div class="empty">لا توجد تحويلات بانتظار الاعتماد.</div>';
  document.querySelectorAll('[data-approve]').forEach(b=>b.onclick=async()=>{await financeAction(b.dataset.approve,'approve');finance(c)});
  document.querySelectorAll('[data-reject]').forEach(b=>b.onclick=async()=>{const reason=prompt('سبب الرفض؟','البيانات غير مطابقة');if(reason===null)return;await financeAction(b.dataset.reject,'reject',reason);finance(c)});
  const sel=document.getElementById('finOffice');sel.innerHTML='<option value="">اختر مكتباً لكشف الحساب</option>'+d.offices.map(o=>`<option value="${o.id}">${esc(o.name)} — ${Number(o.balance||0).toLocaleString('ar-SY')} ${esc(o.currency)}</option>`).join('');sel.onchange=()=>loadStatement(sel.value);await loadFinancePayments();
}
function paymentLabel(p){return p==='moyasar'?'Moyasar':p==='shamcash'?'شام كاش':p==='syriatel_cash'?'سيرياتيل كاش':p||'—'}
async function financeAction(id,action,reason=''){try{await api('/api/admin/finance/payments/'+id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,reason})});show(action==='approve'?'تم اعتماد التحويل وإضافة الرصيد.':action==='reject'?'تم رفض التحويل.':'تم تنفيذ الاسترداد.')}catch(e){show(e.message);throw e}}
async function loadFinancePayments(){const q=encodeURIComponent(document.getElementById('fpq').value),p=encodeURIComponent(document.getElementById('fpp').value),s=encodeURIComponent(document.getElementById('fps').value);const d=await api('/api/admin/finance/payments?q='+q+'&provider='+p+'&status='+s);document.getElementById('allPayments').innerHTML=`<table class="table"><tr><th>رقم</th><th>المكتب</th><th>الطريقة</th><th>المبلغ</th><th>الحالة</th><th>الفاتورة</th><th>التاريخ</th><th>إجراءات</th></tr>${d.data.map(x=>`<tr><td>#${x.id}</td><td>${esc(x.office_name||'—')}</td><td>${paymentLabel(x.provider)}</td><td>${Number(x.amount).toLocaleString('ar-SY')} ${esc(x.currency)}</td><td><span class="badge ${x.status}">${esc(x.status)}</span></td><td>${esc(x.invoice_no||'—')}</td><td>${new Date(x.created_at).toLocaleString('ar-SY')}</td><td class="actions"><a class="btn-link" href="/api/admin/finance/payments/${x.id}/invoice.pdf" target="_blank">PDF</a>${x.status==='paid'?`<button data-refund="${x.id}">استرداد</button>`:''}</td></tr>`).join('')}</table>`;document.querySelectorAll('[data-refund]').forEach(b=>b.onclick=async()=>{if(!confirm('تأكيد استرداد هذه العملية؟'))return;await financeAction(b.dataset.refund,'refund','استرداد من الإدارة');loadFinancePayments()})}
async function loadStatement(id){const el=document.getElementById('statement');if(!id){el.textContent='اختر مكتباً لعرض كشف الحساب.';return}try{const d=await api('/api/admin/finance/statement/'+id);el.innerHTML=`<div class="statement-head"><b>${esc(d.office.name)}</b><span>الرصيد: <strong>${Number(d.wallet?.balance||0).toLocaleString('ar-SY')} ${esc(d.wallet?.currency||'')}</strong></span></div><div class="table-wrap"><table class="table"><tr><th>التاريخ</th><th>النوع</th><th>الوصف</th><th>المبلغ</th><th>الرصيد</th></tr>${d.transactions.map(x=>`<tr><td>${new Date(x.created_at).toLocaleString('ar-SY')}</td><td>${esc(x.type)}</td><td>${esc(x.description||'—')}</td><td>${Number(x.amount).toLocaleString('ar-SY')}</td><td>${Number(x.balance_after).toLocaleString('ar-SY')}</td></tr>`).join('')}</table></div>`}catch(e){el.innerHTML=`<div class="panel">${esc(e.message)}</div>`}}

async function boot(){try{const me=await api('/api/auth/me');if(!me.user){app.innerHTML='<div class="panel"><h2>تسجيل دخول المدير مطلوب</h2><p>افتح الصفحة الرئيسية وسجّل الدخول بحساب مدير.</p><a href="/">العودة للموقع</a></div>';return}if(me.user.role!=='admin'){app.innerHTML='<div class="panel"><h2>غير مصرح</h2><p>هذا القسم مخصص لمديري المنصة فقط.</p></div>';return}shell();await render()}catch(e){app.innerHTML='<div class="panel">تعذر الاتصال بالخادم.</div>'}}
document.getElementById('logout').onclick=async()=>{await fetch('/api/auth/logout',{method:'POST',credentials:'same-origin'});location.href='/'};boot();


async function hotelExecutive(c){
 c.innerHTML=`<div class="finance-toolbar"><select id="hexDays"><option value="7">7 أيام</option><option value="30" selected>30 يوماً</option><option value="90">90 يوماً</option><option value="365">سنة</option></select><button class="gold" id="hexRefresh">تحديث</button></div><div id="hexBody">جاري تحميل مؤشرات الفنادق...</div>`;
 document.getElementById('hexRefresh').onclick=()=>loadHotelExecutive();document.getElementById('hexDays').onchange=()=>loadHotelExecutive();await loadHotelExecutive();
}
async function loadHotelExecutive(){
 const days=document.getElementById('hexDays').value,d=await api('/api/admin/hotels/executive-dashboard?days='+days),k=d.kpis,n=v=>Number(v||0).toLocaleString('ar-SY',{maximumFractionDigits:2});
 document.getElementById('hexBody').innerHTML=`<div class="stats"><div class="stat"><b>${k.hotels}</b><small>الفنادق</small></div><div class="stat"><b>${k.bookings}</b><small>الحجوزات</small></div><div class="stat"><b>${n(k.gross_booking_value)}</b><small>قيمة الحجوزات</small></div><div class="stat"><b>${n(k.platform_commission)}</b><small>عمولة عقارتكم</small></div><div class="stat"><b>${n(k.hotel_net)}</b><small>صافي الفنادق</small></div><div class="stat"><b>${n(k.ota_received)}</b><small>دفعات OTA المستلمة</small></div><div class="stat"><b>${n(k.discrepancies)}</b><small>الفروقات المالية</small></div><div class="stat"><b>${k.open_alerts}</b><small>تنبيهات مفتوحة</small></div></div>
 <div class="finance-grid"><div class="panel"><h3>القنوات</h3><div class="table-wrap"><table class="table"><tr><th>القناة</th><th>الحجوزات</th><th>الإجمالي</th><th>العمولة</th><th>الدفع المتوقع</th></tr>${d.providers.map(x=>`<tr><td>${esc(x.provider)}</td><td>${x.bookings}</td><td>${n(x.gross)}</td><td>${n(x.commission)}</td><td>${n(x.expected_payout)}</td></tr>`).join('')}</table></div></div><div class="panel"><h3>تنبيهات مالية</h3><div class="table-wrap"><table class="table"><tr><th>الفندق</th><th>القناة</th><th>التنبيه</th><th>المبلغ</th></tr>${d.alerts.map(a=>`<tr><td>${esc(a.hotel_name)}</td><td>${esc(a.provider)}</td><td>${a.severity==='high'?'🔴 ':''}${esc(a.message)}</td><td>${n(a.amount)} ${esc(a.currency)}</td></tr>`).join('')}</table></div></div></div>
 <div class="panel"><h3>أداء الفنادق</h3><div class="table-wrap"><table class="table"><tr><th>الفندق</th><th>المدينة</th><th>الحجوزات</th><th>الإجمالي</th><th>عمولة المنصة</th><th>صافي الفندق</th><th>المستلم</th><th>الفروقات</th><th>التنبيهات</th></tr>${d.hotels.map(h=>`<tr><td><b>${esc(h.name)}</b></td><td>${esc(h.city||'—')}</td><td>${h.bookings}</td><td>${n(h.gross)} ${esc(h.currency||'')}</td><td>${n(h.commission)}</td><td>${n(h.hotel_net)}</td><td>${n(h.received)}</td><td>${n(h.variance)}</td><td>${h.alerts?`<span class="badge pending">${h.alerts}</span>`:'0'}</td></tr>`).join('')}</table></div></div>`;
}

async function hotelPayouts(c){
 c.innerHTML=`<div class="panel"><h3>إنشاء دورة تسوية</h3><div class="toolbar"><select id="hpHotel"><option>تحميل الفنادق...</option></select><input id="hpFrom" type="date"><input id="hpTo" type="date"><select id="hpFreq"><option value="weekly">أسبوعية</option><option value="monthly" selected>شهرية</option><option value="manual">يدوية</option></select><button class="gold" id="hpGen">إنشاء</button></div></div><div class="panel"><h3>تحويلات مستحقات الفنادق</h3><div id="hpRows">جاري التحميل...</div></div>`;
 const d=await api('/api/admin/hotels/executive-dashboard?days=365');document.getElementById('hpHotel').innerHTML=d.hotels.map(h=>`<option value="${h.id}">${esc(h.name)}</option>`).join('');const now=new Date(),to=now.toISOString().slice(0,10),from=new Date(now.getFullYear(),now.getMonth(),1).toISOString().slice(0,10);document.getElementById('hpFrom').value=from;document.getElementById('hpTo').value=to;document.getElementById('hpGen').onclick=async()=>{await api('/api/admin/hotel-payouts',{method:'GET'}).catch(()=>{});await api('/api/admin/hotel-payouts/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({hotel_id:hpHotel.value,period_start:hpFrom.value,period_end:hpTo.value,frequency:hpFreq.value})});show('تم إنشاء دورة التسوية');loadHotelPayouts()};await loadHotelPayouts();
}
async function loadHotelPayouts(){const d=await api('/api/admin/hotel-payouts'),n=v=>Number(v||0).toLocaleString('ar-SY',{maximumFractionDigits:2});document.getElementById('hpRows').innerHTML=`<div class="table-wrap"><table class="table"><tr><th>الفندق</th><th>الفترة</th><th>الإجمالي</th><th>العمولة</th><th>الصافي</th><th>الحالة</th><th>إجراء</th></tr>${d.data.map(p=>`<tr><td>${esc(p.hotel_name)}</td><td>${String(p.period_start).slice(0,10)} — ${String(p.period_end).slice(0,10)}</td><td>${n(p.gross_amount)} ${esc(p.currency)}</td><td>${n(p.platform_commission)}</td><td><b>${n(p.payout_amount)}</b></td><td><span class="badge ${esc(p.status)}">${esc(p.status)}</span></td><td class="actions">${p.status==='draft'?`<button class="gold" data-pa="${p.id}">اعتماد</button>`:''}${['approved','processing'].includes(p.status)?`<button class="gold" data-pp="${p.id}">تأكيد التحويل</button>`:''}</td></tr>`).join('')}</table></div>`;document.querySelectorAll('[data-pa]').forEach(b=>b.onclick=async()=>{await payoutAction(b.dataset.pa,'approve');loadHotelPayouts()});document.querySelectorAll('[data-pp]').forEach(b=>b.onclick=async()=>{const ref=prompt('رقم/مرجع التحويل البنكي');if(ref===null)return;await payoutAction(b.dataset.pp,'mark_paid',ref);loadHotelPayouts()})}
async function payoutAction(id,action,bank_reference=''){await api('/api/admin/hotel-payouts/'+id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,bank_reference,payment_method:'bank_transfer'})});show(action==='approve'?'تم اعتماد التسوية':'تم تسجيل التحويل')}

async function hotelAutomation(c){c.innerHTML=`<div class="panel"><div class="toolbar"><h3>التسوية الآلية والدفعات الجماعية</h3><button class="gold" id="haRun">تشغيل الجدولة الآن</button></div><div id="haSettings">تحميل...</div></div><div class="panel"><h3>تجهيز دفعة جماعية</h3><div id="haEligible">تحميل...</div><button class="gold" id="haBatch">إنشاء دفعة من المحدد</button></div><div class="panel"><h3>الدفعات الجماعية</h3><div id="haBatches"></div></div><div class="panel"><h3>السجل المحاسبي المركزي</h3><div id="haLedger"></div></div>`;haRun.onclick=async()=>{await api('/api/admin/hotel-payout-automation/run',{method:'POST'});show('تم تشغيل الجدولة');loadHotelAutomation()};haBatch.onclick=createHotelBatch;await loadHotelAutomation()}
async function loadHotelAutomation(){const [a,p,l]=await Promise.all([api('/api/admin/hotel-payout-automation'),api('/api/admin/hotel-payouts'),api('/api/admin/hotel-accounting-ledger')]),n=v=>Number(v||0).toLocaleString('ar-SY',{maximumFractionDigits:2});haSettings.innerHTML=`<div class="table-wrap"><table class="table"><tr><th>الفندق</th><th>التكرار</th><th>تلقائي</th><th>تدقيق الفروقات</th><th>آخر فترة</th><th></th></tr>${a.settings.map(x=>`<tr><td>${esc(x.name)}</td><td><select id="freq${x.hotel_id}"><option value="monthly" ${x.frequency==='monthly'?'selected':''}>شهري</option><option value="weekly" ${x.frequency==='weekly'?'selected':''}>أسبوعي</option></select></td><td><input id="auto${x.hotel_id}" type="checkbox" ${x.auto_generate?'checked':''}></td><td><input id="clean${x.hotel_id}" type="checkbox" ${x.require_clean_reconciliation?'checked':''}></td><td>${x.last_generated_through?String(x.last_generated_through).slice(0,10):'—'}</td><td><button data-save-auto="${x.hotel_id}">حفظ</button></td></tr>`).join('')}</table></div>`;document.querySelectorAll('[data-save-auto]').forEach(b=>b.onclick=async()=>{const id=b.dataset.saveAuto;await api('/api/admin/hotel-payout-automation/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({frequency:document.getElementById('freq'+id).value,auto_generate:document.getElementById('auto'+id).checked,require_clean_reconciliation:document.getElementById('clean'+id).checked})});show('تم حفظ إعدادات الفندق')});const eligible=p.data.filter(x=>x.status==='approved');haEligible.innerHTML=eligible.length?`<div class="table-wrap"><table class="table"><tr><th></th><th>الفندق</th><th>الفترة</th><th>الصافي</th><th>فحص</th></tr>${eligible.map(x=>`<tr><td><input type="checkbox" class="batchPick" value="${x.id}"></td><td>${esc(x.hotel_name)}</td><td>${String(x.period_start).slice(0,10)} — ${String(x.period_end).slice(0,10)}</td><td>${n(x.payout_amount)} ${esc(x.currency)}</td><td><button data-check="${x.id}">فحص</button></td></tr>`).join('')}</table></div>`:'لا توجد تسويات معتمدة جاهزة.';document.querySelectorAll('[data-check]').forEach(b=>b.onclick=async()=>{const w=await api('/api/admin/hotel-payouts/'+b.dataset.check+'/check');show(w.blocked?`موقوف: فروقات ${n(w.variance)} / غير مطابق ${w.unmatched}`:'التسوية سليمة وجاهزة')});haBatches.innerHTML=`<div class="table-wrap"><table class="table"><tr><th>الدفعة</th><th>العدد</th><th>الإجمالي</th><th>الحالة</th><th>إجراء</th></tr>${a.batches.map(b=>`<tr><td>${esc(b.batch_code)}</td><td>${b.payout_count}</td><td>${n(b.total_amount)} ${esc(b.currency)}</td><td>${esc(b.status)}</td><td>${b.status==='draft'?`<button data-ba="${b.id}">اعتماد</button>`:''}${['approved','processing'].includes(b.status)?`<button class="gold" data-bp="${b.id}">تسجيل الدفع</button>`:''}</td></tr>`).join('')}</table></div>`;document.querySelectorAll('[data-ba]').forEach(b=>b.onclick=async()=>{await batchAct(b.dataset.ba,'approve');loadHotelAutomation()});document.querySelectorAll('[data-bp]').forEach(b=>b.onclick=async()=>{const ref=prompt('مرجع التحويل الجماعي');if(ref===null)return;await batchAct(b.dataset.bp,'mark_paid',ref);loadHotelAutomation()});haLedger.innerHTML=`<div class="table-wrap"><table class="table"><tr><th>التاريخ</th><th>الفندق</th><th>النوع</th><th>المبلغ</th><th>المرجع</th></tr>${l.data.map(x=>`<tr><td>${new Date(x.created_at).toLocaleString('ar-SY')}</td><td>${esc(x.hotel_name||'—')}</td><td>${esc(x.entry_type)}</td><td>${n(x.amount)} ${esc(x.currency)}</td><td>${esc(x.reference||x.batch_code||'—')}</td></tr>`).join('')}</table></div>`}
async function createHotelBatch(){const ids=[...document.querySelectorAll('.batchPick:checked')].map(x=>Number(x.value));if(!ids.length)return show('حدد تسوية واحدة على الأقل');await api('/api/admin/hotel-payout-batches',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({payout_ids:ids})});show('تم إنشاء الدفعة الجماعية');loadHotelAutomation()}
async function batchAct(id,action,bank_reference=''){await api('/api/admin/hotel-payout-batches/'+id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,bank_reference})});show(action==='approve'?'تم اعتماد الدفعة':'تم تسجيل دفع الدفعة')}


async function accounting(c){
 const now=new Date();c.innerHTML=`<div class="panel"><div class="toolbar"><h3>المحاسبة المتكاملة</h3><select id="accYear"></select><select id="accMonth"><option value="0">السنة كاملة</option>${Array.from({length:12},(_,i)=>`<option value="${i+1}">${i+1}</option>`).join('')}</select><button class="gold" id="accLoad">تحديث</button><button id="accCsv">CSV</button></div><div id="accBody">تحميل...</div></div><div class="finance-grid"><div class="panel"><h3>إضافة مصروف</h3><div class="toolbar"><input id="exDate" type="date"><input id="exCat" placeholder="التصنيف" value="تشغيل"><input id="exVendor" placeholder="المورد"><input id="exAmount" type="number" step="0.01" placeholder="المبلغ"><input id="exTax" type="number" step="0.01" placeholder="الضريبة"><button class="gold" id="exAdd">حفظ المصروف</button></div><div id="exRows"></div></div><div class="panel"><h3>الذمم المدينة والدائنة</h3><div id="accArap"></div></div></div>`;
 for(let y=now.getFullYear();y>=now.getFullYear()-5;y--)accYear.innerHTML+=`<option ${y===now.getFullYear()?'selected':''}>${y}</option>`;exDate.value=now.toISOString().slice(0,10);accMonth.value=now.getMonth()+1;accLoad.onclick=loadAccounting;accCsv.onclick=()=>location.href=`/api/admin/accounting/report.csv?year=${accYear.value}&month=${accMonth.value}`;exAdd.onclick=async()=>{await api('/api/admin/accounting/expenses',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({expense_date:exDate.value,category:exCat.value,vendor:exVendor.value,amount:Number(exAmount.value),tax_amount:Number(exTax.value||0)})});show('تم تسجيل المصروف');exAmount.value='';exTax.value='';loadAccounting()};await loadAccounting();
}
async function loadAccounting(){const q=`year=${accYear.value}&month=${accMonth.value}`,[d,e,ar]=await Promise.all([api('/api/admin/accounting/dashboard?'+q),api('/api/admin/accounting/expenses?'+q),api('/api/admin/accounting/receivables-payables')]),n=v=>Number(v||0).toLocaleString('ar-SY',{maximumFractionDigits:2});accBody.innerHTML=`<div class="stats"><div class="stat"><b>${n(d.kpis.revenue)}</b><small>الإيرادات</small></div><div class="stat"><b>${n(d.kpis.expenses)}</b><small>المصروفات</small></div><div class="stat"><b>${n(d.kpis.profit)}</b><small>صافي الربح</small></div><div class="stat"><b>${n(d.kpis.hotel_commission)}</b><small>عمولات الفنادق</small></div><div class="stat"><b>${n(d.kpis.realestate_commission)}</b><small>عمولات العقارات</small></div><div class="stat"><b>${n(d.kpis.accounts_receivable)}</b><small>ذمم مدينة</small></div><div class="stat"><b>${n(d.kpis.accounts_payable)}</b><small>ذمم دائنة</small></div><div class="stat"><b>${n(d.kpis.input_tax)}</b><small>ضريبة مدخلات</small></div></div><div class="table-wrap"><table class="table"><tr><th>الشهر</th><th>الإيراد</th><th>المصروف</th><th>الربح</th></tr>${d.monthly.map(x=>`<tr><td>${x.month}</td><td>${n(x.revenue)}</td><td>${n(x.expenses)}</td><td><b>${n(Number(x.revenue)-Number(x.expenses))}</b></td></tr>`).join('')}</table></div>`;exRows.innerHTML=`<div class="table-wrap"><table class="table"><tr><th>التاريخ</th><th>التصنيف</th><th>المورد</th><th>المبلغ</th><th>الضريبة</th></tr>${e.data.map(x=>`<tr><td>${String(x.expense_date).slice(0,10)}</td><td>${esc(x.category)}</td><td>${esc(x.vendor||'—')}</td><td>${n(x.amount)} ${esc(x.currency)}</td><td>${n(x.tax_amount)}</td></tr>`).join('')}</table></div>`;accArap.innerHTML=`<h4>مدينة</h4><div class="table-wrap"><table class="table"><tr><th>الفندق</th><th>المرجع</th><th>الرصيد</th></tr>${ar.receivables.slice(0,20).map(x=>`<tr><td>${esc(x.hotel_name)}</td><td>${esc(x.invoice_number)}</td><td>${n(x.balance)} ${esc(x.currency)}</td></tr>`).join('')}</table></div><h4>دائنة للفنادق</h4><div class="table-wrap"><table class="table"><tr><th>الفندق</th><th>الفترة</th><th>الرصيد</th></tr>${ar.payables.slice(0,20).map(x=>`<tr><td>${esc(x.hotel_name)}</td><td>${String(x.period_end).slice(0,10)}</td><td>${n(x.balance)} ${esc(x.currency)}</td></tr>`).join('')}</table></div>`}


async function einvoices(c){c.innerHTML=`<div class="panel"><div class="toolbar"><h3>الفوترة الإلكترونية</h3><button class="gold" id="eiNew">فاتورة جديدة</button><select id="eiStatus"><option value="">كل الحالات</option><option value="issued">صادرة</option><option value="partially_paid">مسددة جزئياً</option><option value="paid">مسددة</option></select></div><div id="eiRows">تحميل...</div></div>`;eiNew.onclick=newEinvoice;eiStatus.onchange=loadEinvoices;await loadEinvoices()}
async function loadEinvoices(){const r=await api('/api/admin/einvoices?status='+encodeURIComponent(eiStatus.value)),n=v=>Number(v||0).toLocaleString('ar-SY',{maximumFractionDigits:2});eiRows.innerHTML=`<div class="table-wrap"><table class="table"><tr><th>الرقم</th><th>النوع</th><th>العميل</th><th>الإجمالي</th><th>المدفوع</th><th>الحالة</th><th>إجراء</th></tr>${r.data.map(x=>`<tr><td>${esc(x.invoice_number)}</td><td>${esc(x.document_type)}</td><td>${esc(x.customer_name)}</td><td>${n(x.total_amount)} ${esc(x.currency)}</td><td>${n(x.paid_amount)}</td><td>${esc(x.status)}</td><td><button onclick="window.open('/api/admin/einvoices/${x.id}/pdf','_blank')">PDF</button> <button onclick="window.open('/api/admin/einvoices/${x.id}/qr','_blank')">QR</button>${x.status!=='paid'?` <button class="gold" data-eipay="${x.id}" data-bal="${Number(x.total_amount)-Number(x.paid_amount)}">سداد</button>`:''}</td></tr>`).join('')}</table></div>`;document.querySelectorAll('[data-eipay]').forEach(b=>b.onclick=async()=>{const amount=prompt('مبلغ السداد',b.dataset.bal);if(!amount)return;const reference=prompt('مرجع السداد')||'';await api('/api/admin/einvoices/'+b.dataset.eipay+'/payments',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({amount:Number(amount),reference})});show('تم تسجيل السداد');loadEinvoices()})}
async function newEinvoice(){const customer_name=prompt('اسم العميل / الفندق / المكتب');if(!customer_name)return;const description=prompt('وصف البند','خدمات منصة عقارتكم');if(!description)return;const unit_price=Number(prompt('المبلغ قبل الضريبة','0'));const tax_rate=Number(prompt('نسبة الضريبة %','0'));const currency=prompt('العملة','SAR')||'SAR';const document_type=prompt('النوع: invoice أو credit_note أو debit_note','invoice')||'invoice';await api('/api/admin/einvoices',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({customer_name,currency,document_type,items:[{description,quantity:1,unit_price,tax_rate}]})});show('تم إصدار المستند الإلكتروني');loadEinvoices()}


async function executiveBI(c){
 c.innerHTML=`<div class="panel"><div class="toolbar"><h3>لوحة ذكاء الأعمال والإدارة التنفيذية</h3><select id="biDays"><option value="7">7 أيام</option><option value="30" selected>30 يوماً</option><option value="90">90 يوماً</option><option value="365">365 يوماً</option></select><button class="gold" id="biLoad">تحديث</button></div><div id="biBody">تحميل المؤشرات...</div></div>`;
 biLoad.onclick=loadExecutiveBI;await loadExecutiveBI();
}
async function loadExecutiveBI(){
 const d=await api('/api/admin/executive-bi?days='+biDays.value),n=v=>Number(v||0).toLocaleString('ar-SY',{maximumFractionDigits:2}),pct=v=>`${Number(v||0).toFixed(1)}%`;
 const k=d.kpis,trend=Number(k.revenue_growth_pct)>=0?'▲':'▼';
 biBody.innerHTML=`<div class="stats"><div class="stat"><b>${n(k.revenue)}</b><small>إيرادات الفترة</small></div><div class="stat"><b>${n(k.profit)}</b><small>صافي الربح</small></div><div class="stat"><b>${trend} ${pct(Math.abs(k.revenue_growth_pct))}</b><small>نمو الإيراد مقابل الفترة السابقة</small></div><div class="stat"><b>${n(k.forecast_next_30_days)}</b><small>توقع إيراد 30 يوماً</small></div><div class="stat"><b>${n(k.bookings)}</b><small>حجوزات الفنادق</small></div><div class="stat"><b>${n(k.completed_deals)}</b><small>صفقات عقارية مكتملة</small></div><div class="stat"><b>${n(k.active_properties)}</b><small>عقارات نشطة</small></div><div class="stat"><b>${n(k.active_hotels)}</b><small>فنادق نشطة</small></div></div>
 <div class="finance-grid"><div class="panel"><h3>الإيرادات والمصروفات — 12 شهراً</h3><div class="table-wrap"><table class="table"><tr><th>الشهر</th><th>الإيرادات</th><th>المصروفات</th><th>الربح</th></tr>${d.monthly.map(x=>`<tr><td>${x.month}</td><td>${n(x.revenue)}</td><td>${n(x.expenses)}</td><td><b>${n(Number(x.revenue)-Number(x.expenses))}</b></td></tr>`).join('')}</table></div><small>${esc(d.forecast_note)}</small></div><div class="panel"><h3>تنبيهات الإدارة</h3>${d.alerts.length?d.alerts.map(a=>`<div class="stat" style="margin-bottom:8px"><b>${n(a.value)}</b><small>${esc(a.title)}</small></div>`).join(''):'<p>لا توجد تنبيهات تشغيلية حالياً.</p>'}</div></div>
 <div class="finance-grid"><div class="panel"><h3>أفضل الفنادق</h3><div class="table-wrap"><table class="table"><tr><th>الفندق</th><th>المدينة</th><th>الحجوزات</th><th>القيمة</th></tr>${d.top_hotels.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.city)}</td><td>${n(x.bookings)}</td><td>${n(x.booking_value)}</td></tr>`).join('')}</table></div></div><div class="panel"><h3>أفضل المكاتب العقارية</h3><div class="table-wrap"><table class="table"><tr><th>المكتب</th><th>المدينة</th><th>الصفقات</th><th>قيمة الصفقات</th><th>عمولة المنصة</th></tr>${d.top_offices.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.city||'—')}</td><td>${n(x.deals)}</td><td>${n(x.deal_value)}</td><td>${n(x.platform_commission)}</td></tr>`).join('')}</table></div></div></div>
 <div class="panel"><h3>أداء المدن</h3><div class="table-wrap"><table class="table"><tr><th>المدينة</th><th>العقارات النشطة</th><th>الفنادق</th><th>الحجوزات</th></tr>${d.cities.map(x=>`<tr><td><b>${esc(x.city)}</b></td><td>${n(x.property_count)}</td><td>${n(x.hotel_count)}</td><td>${n(x.booking_count)}</td></tr>`).join('')}</table></div></div>`;
}


async function propertyAI(c){
 c.innerHTML=`<div class="panel"><div class="toolbar"><button class="gold" id="aiRecalc">إعادة تحليل جميع العقارات</button><select id="aiFilter"><option value="">كل النتائج</option><option value="above_market">أعلى من السوق</option><option value="below_market">أقل من السوق</option><option value="fair">سعر قريب من السوق</option><option value="duplicate">اشتباه تكرار</option></select></div><div id="aiStats"></div><p><small>التقديرات إرشادية مبنية على الإعلانات الداخلية المقارنة وليست تقييماً عقارياً معتمداً.</small></p></div><div class="panel"><div class="table-wrap" id="aiTable">جاري التحميل...</div></div>`;
 aiRecalc.onclick=async()=>{aiRecalc.disabled=true;aiRecalc.textContent='جاري التحليل...';try{const x=await api('/api/admin/property-ai/recalculate',{method:'POST'});show(`تم تحليل ${x.data.processed} عقار`);await loadPropertyAI()}finally{aiRecalc.disabled=false;aiRecalc.textContent='إعادة تحليل جميع العقارات'}};aiFilter.onchange=loadPropertyAI;await loadPropertyAI();
}
