async function loadMarketMap(){const d=await api('/api/admin/market-map/dashboard'),n=v=>Number(v||0).toLocaleString('ar-SY',{maximumFractionDigits:1});let cs=d.cities||[],hs=d.hotspots||[];if(mmMode.value){hs=hs.filter(x=>x.mode===mmMode.value)}const top=hs[0]||{};mmStats.innerHTML=`<div class="stats"><div class="stat"><b>${n(cs.length)}</b><small>مدن محللة</small></div><div class="stat"><b>${esc(top.city||'—')}</b><small>أعلى فرصة استثمارية</small></div><div class="stat"><b>${n(top.investment_score)}/100</b><small>مؤشر الاستثمار</small></div><div class="stat"><b>${n(top.demand_score)}/100</b><small>مؤشر الطلب</small></div></div>`;mmCities.innerHTML=`<table class="table"><tr><th>المدينة</th><th>سعر المتر</th><th>الطلب</th><th>الاستثمار</th><th>الاتجاه</th></tr>${cs.map(x=>`<tr><td><b>${esc(x.city)}</b></td><td>${n(x.price_per_sqm)}</td><td>${n(x.demand_score)}/100</td><td>${n(x.investment_score)}/100</td><td>${Number(x.price_trend_pct||0)>=0?'▲':'▼'} ${n(Math.abs(x.price_trend_pct))}%</td></tr>`).join('')}</table>`;mmHot.innerHTML=`<table class="table"><tr><th>المنطقة</th><th>النوع</th><th>سعر المتر</th><th>الطلب</th><th>فرصة الاستثمار</th></tr>${hs.map(x=>`<tr><td><b>${esc(x.city)} — ${esc(x.district||'')}</b></td><td>${esc(x.mode)} / ${esc(x.property_type||'')}</td><td>${n(x.median_price_per_sqm)}</td><td>${n(x.demand_score)}/100</td><td><b>${n(x.investment_score)}/100</b></td></tr>`).join('')}</table>`;if(geoCity.options.length===1)cs.forEach(x=>geoCity.add(new Option(x.city,x.city)));await loadGeoMap()}
function fitGeoMap(){if(!geoMap||!geoMarkers)return;const b=geoMarkers.getBounds();if(b.isValid())geoMap.fitBounds(b.pad(.12))}
async function loadGeoMap(){if(typeof L==='undefined'){geoNote.textContent='تعذر تحميل مكتبة الخريطة. تحقق من اتصال الإنترنت.';return}const q=new URLSearchParams();if(geoCity.value)q.set('city',geoCity.value);if(mmMode.value)q.set('mode',mmMode.value);if(geoType.value)q.set('type',geoType.value);const d=await api('/api/admin/market-map/geo?'+q),pts=d.points||[],ds=d.districts||[];if(geoType.options.length===1)[...new Set(pts.map(x=>x.type).filter(Boolean))].sort().forEach(x=>geoType.add(new Option(x,x)));if(!geoMap){geoMap=L.map('geoMarketMap',{preferCanvas:true}).setView([34.8,38.8],6);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(geoMap)}if(geoHeat)geoMap.removeLayer(geoHeat);if(geoMarkers)geoMap.removeLayer(geoMarkers);geoMarkers=L.featureGroup().addTo(geoMap);const metric=geoMetric.value;const raw=pts.map(x=>metric==='price'?Number(x.price_per_sqm||0):metric==='demand'?Math.log1p(Number(x.views_count||0)):Number(x.investment_score||0));const max=Math.max(1,...raw);const heat=pts.map((x,i)=>[Number(x.latitude),Number(x.longitude),Math.max(.08,raw[i]/max)]).filter(x=>Number.isFinite(x[0])&&Number.isFinite(x[1]));geoHeat=L.heatLayer(heat,{radius:32,blur:24,maxZoom:15,minOpacity:.25}).addTo(geoMap);if(geoPoints.checked)pts.forEach(x=>{const m=L.circleMarker([Number(x.latitude),Number(x.longitude)],{radius:5,weight:1,fillOpacity:.75});m.bindPopup(`<b>${esc(x.title)}</b><br>${esc(x.city)} — ${esc(x.district||'')}<br>${esc(x.mode)} / ${esc(x.type)}<br>السعر: ${Number(x.price||0).toLocaleString('ar-SY')} ${esc(x.currency)}<br>سعر المتر: ${Number(x.price_per_sqm||0).toLocaleString('ar-SY',{maximumFractionDigits:0})}<br><a href="/property.html?id=${encodeURIComponent(x.id)}" target="_blank">فتح العقار</a>`);m.addTo(geoMarkers)});ds.forEach(x=>{const r=Math.max(8,Math.min(28,7+Math.sqrt(Number(x.listings||1))*3));L.circleMarker([Number(x.latitude),Number(x.longitude)],{radius:r,weight:2,fillOpacity:.12}).bindTooltip(`${esc(x.city)} — ${esc(x.district||'')}: ${x.listings} عقار`).addTo(geoMarkers)});geoNote.textContent=`${pts.length} عقار بإحداثيات • ${ds.length} منطقة • ${d.disclaimer}`;if(pts.length&&!geoMap._v37Fitted){fitGeoMap();geoMap._v37Fitted=true}}


