async function loadExecutiveDashboard(){
 const [open,done,dismissed]=await Promise.all([api('/api/admin/ai-executive?status=proposed&limit=50'),api('/api/admin/ai-executive?status=executed&limit=20'),api('/api/admin/ai-executive?status=dismissed&limit=20')]);
 const ps=open.proposals||[], high=ps.filter(x=>x.priority==='high'||x.priority==='critical').length, finance=ps.filter(x=>x.category==='finance').length;
 const body=document.getElementById('execBody'); if(!body)return;
 body.innerHTML=`<div class="exec-stats"><div><b>${ps.length}</b><span>بانتظار قرارك</span></div><div><b>${high}</b><span>أولوية عالية</span></div><div><b>${finance}</b><span>تنبيهات مالية</span></div><div><b>${(done.proposals||[]).length}</b><span>إجراءات منفذة</span></div></div>
 <div class="exec-layout"><section class="exec-card"><div class="exec-card-head"><div><h3>مركز القرارات</h3><small>راجع المقترحات قبل التنفيذ</small></div><span class="exec-live">● مباشر</span></div><div class="exec-proposals">${ps.length?ps.map(p=>`<article class="exec-proposal priority-${esc(p.priority)}"><div class="exec-proposal-top"><span class="exec-priority">${esc(execPriority(p.priority))}</span><span>${esc(execCategory(p.category))}</span><span>مخاطر: ${esc(execPriority(p.risk_level))}</span></div><h4>${esc(p.title)}</h4><p>${esc(p.rationale)}</p><div class="exec-actions"><button class="exec-approve" data-exec-approve="${p.id}">موافقة وتنفيذ</button><button data-exec-dismiss="${p.id}">رفض المقترح</button></div></article>`).join(''):'<div class="exec-empty">لا توجد مقترحات معلقة حالياً.</div>'}</div></section>
 <aside class="exec-card exec-chat"><div class="exec-card-head"><div><h3>محادثة ChatGPT</h3><small>اسأل عن التشغيل والأولويات</small></div></div><div id="execMessages" class="exec-messages"><div class="exec-ai-msg">مرحباً. أستطيع فحص حالة عقارتكم وشرح المشكلات واقتراح الإجراء المناسب. التنفيذ يبقى خاضعاً لموافقتك.</div></div><form id="execChatForm" class="exec-chat-form"><textarea id="execChatInput" rows="3" placeholder="مثال: ما أهم المشاكل التي تحتاج تدخلي اليوم؟"></textarea><button>إرسال</button></form></aside></div>
 <section class="exec-card"><div class="exec-card-head"><div><h3>سجل القرارات</h3><small>آخر ما تم تنفيذه أو رفضه</small></div></div><div class="exec-history">${[...(done.proposals||[]).map(x=>({...x,_state:'تم التنفيذ'})),...(dismissed.proposals||[]).map(x=>({...x,_state:'مرفوض'}))].sort((a,b)=>new Date(b.detected_at)-new Date(a.detected_at)).slice(0,20).map(x=>`<div><span class="exec-dot"></span><b>${esc(x.title)}</b><small>${esc(x._state)} · ${new Date(x.detected_at).toLocaleString('ar-SY')}</small></div>`).join('')||'<div class="exec-empty">لا يوجد سجل بعد.</div>'}</div></section>`;
 document.querySelectorAll('[data-exec-approve]').forEach(b=>b.onclick=async()=>{const confirmation=prompt(`للتنفيذ اكتب حرفياً: ${open.confirmation_text}`);if(confirmation===null)return;try{await api(`/api/admin/ai-executive/proposals/${b.dataset.execApprove}/execute`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirmation})});show('تم تنفيذ القرار وتسجيله');loadExecutiveDashboard()}catch(e){show(e.message)}});
 document.querySelectorAll('[data-exec-dismiss]').forEach(b=>b.onclick=async()=>{const reason=prompt('سبب الرفض (اختياري)')||'';try{await api(`/api/admin/ai-executive/proposals/${b.dataset.execDismiss}/dismiss`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reason})});show('تم رفض المقترح');loadExecutiveDashboard()}catch(e){show(e.message)}});
 document.getElementById('execChatForm').onsubmit=async e=>{e.preventDefault();const inp=document.getElementById('execChatInput'),m=inp.value.trim();if(!m)return;const box=document.getElementById('execMessages');box.insertAdjacentHTML('beforeend',`<div class="exec-user-msg">${esc(m)}</div>`);inp.value='';box.insertAdjacentHTML('beforeend','<div class="exec-ai-msg exec-thinking">جاري التحليل...</div>');box.scrollTop=box.scrollHeight;try{const r=await api('/api/admin/ai-executive/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:m})});box.querySelector('.exec-thinking')?.remove();box.insertAdjacentHTML('beforeend',`<div class="exec-ai-msg">${esc(r.reply).replace(/\n/g,'<br>')}</div>`)}catch(err){box.querySelector('.exec-thinking')?.remove();box.insertAdjacentHTML('beforeend',`<div class="exec-ai-msg">${esc(err.message)}</div>`)}box.scrollTop=box.scrollHeight};
}


