let execVoiceRecognition=null,execVoiceListening=false;
function getSpeechRecognition(){return window.SpeechRecognition||window.webkitSpeechRecognition||null}
function speakExecutive(text){if(!('speechSynthesis' in window)||!text)return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(String(text));u.lang='ar-SA';u.rate=.95;window.speechSynthesis.speak(u)}
function setVoiceButton(active,label){const b=document.getElementById('execVoice');if(!b)return;b.classList.toggle('listening',!!active);b.textContent=label||(active?'⏹️ إيقاف الاستماع':'🎙️ تحدث مع المدير')}
async function sendExecutiveVoice(text){const box=document.getElementById('execMessages'),inp=document.getElementById('execChatInput');if(!box||!text)return;if(inp)inp.value='';box.insertAdjacentHTML('beforeend',`<div class="exec-user-msg"><small>🎙️ أمر صوتي</small><br>${esc(text)}</div><div class="exec-ai-msg exec-voice-thinking">جاري التحليل...</div>`);box.scrollTop=box.scrollHeight;try{const r=await api('/api/admin/ai-executive/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:text,channel:'voice'})});box.querySelector('.exec-voice-thinking')?.remove();box.insertAdjacentHTML('beforeend',`<div class="exec-ai-msg">${esc(r.reply).replace(/\n/g,'<br>')}</div>`);speakExecutive(r.reply)}catch(e){box.querySelector('.exec-voice-thinking')?.remove();box.insertAdjacentHTML('beforeend',`<div class="exec-ai-msg">${esc(e.message)}</div>`)}box.scrollTop=box.scrollHeight}
function toggleExecutiveVoice(){const SR=getSpeechRecognition();if(!SR){show('التعرف الصوتي غير مدعوم في هذا المتصفح. يمكنك استخدام مربع المحادثة.');return}if(execVoiceListening&&execVoiceRecognition){execVoiceRecognition.stop();return}const r=new SR();execVoiceRecognition=r;r.lang='ar-SA';r.interimResults=true;r.continuous=false;let finalText='';r.onstart=()=>{execVoiceListening=true;setVoiceButton(true);show('أستمع الآن... تحدث بالعربية')};r.onresult=e=>{let interim='';for(let i=e.resultIndex;i<e.results.length;i++){const t=e.results[i][0].transcript;if(e.results[i].isFinal)finalText+=t;else interim+=t}const inp=document.getElementById('execChatInput');if(inp)inp.value=finalText||interim};r.onerror=e=>{if(e.error!=='aborted')show('تعذر التقاط الصوت: '+e.error)};r.onend=()=>{execVoiceListening=false;setVoiceButton(false);const t=(finalText||document.getElementById('execChatInput')?.value||'').trim();if(t)sendExecutiveVoice(t)};r.start()}


// V57 — continuous two-way Arabic voice conversation
let realtimePc=null,realtimeDc=null,realtimeStream=null,realtimeActive=false;
function setLiveVoiceButton(active,label){const b=document.getElementById('execLiveVoice');if(!b)return;b.classList.toggle('listening',!!active);b.textContent=label||(active?'⏹️ إنهاء Realtime':'⚡ Realtime صوت مباشر')}
function addRealtimeMessage(kind,text){const box=document.getElementById('execMessages');if(!box||!text)return;box.insertAdjacentHTML('beforeend',`<div class="${kind==='user'?'exec-user-msg':'exec-ai-msg'}"><small>${kind==='user'?'🎙️ أنت':'⚡ المدير Realtime'}</small><br>${esc(text)}</div>`);box.scrollTop=box.scrollHeight}
async function stopLiveExecutiveVoice(){realtimeActive=false;try{realtimeDc?.close()}catch{}try{realtimePc?.close()}catch{}try{realtimeStream?.getTracks().forEach(t=>t.stop())}catch{}realtimeDc=realtimePc=realtimeStream=null;setLiveVoiceButton(false);show('تم إنهاء جلسة Realtime')}
async function startRealtimeExecutiveVoice(){if(!window.RTCPeerConnection||!navigator.mediaDevices?.getUserMedia){show('WebRTC أو الميكروفون غير مدعوم على هذا الجهاز.');return}setLiveVoiceButton(true,'⏳ جاري الاتصال...');try{const pc=new RTCPeerConnection();realtimePc=pc;const audio=document.createElement('audio');audio.autoplay=true;audio.style.display='none';document.body.appendChild(audio);pc.ontrack=e=>{audio.srcObject=e.streams[0]};const stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true}});realtimeStream=stream;stream.getTracks().forEach(t=>pc.addTrack(t,stream));const dc=pc.createDataChannel('oai-events');realtimeDc=dc;dc.onopen=()=>{realtimeActive=true;setLiveVoiceButton(true,'🔴 Realtime متصل — اضغط للإنهاء');show('اتصال صوتي مباشر مع المدير التنفيذي')};dc.onmessage=e=>{try{const x=JSON.parse(e.data);if(x.type==='conversation.item.input_audio_transcription.completed'&&x.transcript)addRealtimeMessage('user',x.transcript);if((x.type==='response.output_audio_transcript.done'||x.type==='response.audio_transcript.done')&&x.transcript)addRealtimeMessage('assistant',x.transcript);if(x.type==='error')console.warn('Realtime',x.error)}catch{}};pc.onconnectionstatechange=()=>{if(['failed','closed','disconnected'].includes(pc.connectionState)&&realtimeActive)stopLiveExecutiveVoice()};const offer=await pc.createOffer();await pc.setLocalDescription(offer);const r=await fetch('/api/admin/realtime-voice/call',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sdp:offer.sdp})});if(!r.ok){let j={};try{j=await r.json()}catch{}throw Error(j.error||'تعذر إنشاء جلسة Realtime')}const answer=await r.text();await pc.setRemoteDescription({type:'answer',sdp:answer})}catch(e){await stopLiveExecutiveVoice();show(e.message)}}
function toggleLiveExecutiveVoice(){if(realtimeActive||realtimePc)return stopLiveExecutiveVoice();startRealtimeExecutiveVoice()}


